/// <summary>
/// SalesOrderLineCDSV2Entity COC class
/// </summary>
[ExtensionOf(tableStr(SalesOrderLineCDSV2Entity))]
final class METSalesOrderLineCDSV2Entity_Extension
{
    #OCCRetryCount

}

Method.Source:
    /// <summary>
    /// CoC method for InsertEntityDataSource method
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        SalesLine                       metSalesLineStd;
        boolean                         metCancelSalesLine;

        if (_dataSourceCtx.name() == dataentitydatasourcestr(SalesOrderLineCDSV2Entity, SalesOrderLineEntity) &&
            _entityCtx.isDatabaseOperationInsert())
        {           
            // CB246_LicenseChecks
            // New field to trigger cancel after insert
            if (this.METStatusCancelled)
            {
                metCancelSalesLine  = true;
            }
        }

        boolean ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx); 

        if (_dataSourceCtx.name() == dataentitydatasourcestr(SalesOrderLineCDSV2Entity, SalesOrderLineEntity))
        {
            SalesOrderLineV2Entity  metSalesorderLineEntityStd  = _dataSourceCtx.getBuffer();
            METSalesLine            metSalesLineUpdate;
            PurchLine               purchLine;

            select firstonly metSalesLineStd
                where metSalesLineStd.InventTransId == metSalesorderLineEntityStd.InventoryLotId
                outer join METSalesLineUpdate
                    where METSalesLineUpdate.SalesLine  == metSalesLineStd.RecId;

            if(metCancelSalesLine|| METSalesLineStatus::find(metSalesLineUpdate.ReasonId).ApplyLogic)
            {
                metSalesLineStd.metCancelSalesOrderLine();
                
                //NS - KK, Task 269070: CB887 - BlueYonder to D365 (Intercompany Replenishment)
                if (metSalesLineStd.METReplenishmentPOReference)
                {
                    changecompany(InventParameters::find().METInterCompanyPurchaseLegalEntity)
                    {
                        select firstonly purchLine
                            where purchLine.METReplenishmentSOReference == metSalesLineStd.SalesId
                            && purchLine.ItemId == metSalesLineStd.ItemId
                            && purchLine.PurchUnit == metSalesLineStd.SalesUnit;

                        if (purchLine.RecId)
                        {
                            purchLine.metCancelPurchLineFromSalesLine();
                        }
                    }
                }
                //NE - KK, Task 269070: CB887 - BlueYonder to D365 (Intercompany Replenishment)
                
                // CB246_LicenseChecks
                // reflect the cancelled status in the output payload
                this.SalesOrderLineStatus = metSalesLineStd.SalesStatus;
            }
            //NS - KK, Task 269070: CB887 - BlueYonder to D365 (Intercompany Replenishment)
            if (metSalesLineUpdate.SubstitutionType && metSalesLineStd.METReplenishmentPOReference)
            {
                changecompany(InventParameters::find().METInterCompanyPurchaseLegalEntity)
                {
                    purchLine.copyToNewLineFromNewSalesLine(metSalesLineStd);
                }
            }
            //NE - KK, Task 269070: CB887 - BlueYonder to D365 (Intercompany Replenishment)
        }
    
        return ret;
    }

    /// <summary>
    /// CoC method for updateEntityDataSource method
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        boolean                         metCancelSalesLine;
        boolean                         qtyFieldUpdated;
        SalesLine                       salesLineOrig;

        /// CB_202 SalesQuota changes by Akshay
        if (_dataSourceCtx.name() == dataentitydatasourcestr(SalesOrderLineCDSV2Entity, SalesOrderLineEntity) &&
            _entityCtx.isDatabaseOperationUpdate())
        {
            SalesOrderLineV2Entity  metSalesorderLineEntityStd   = _dataSourceCtx.getBuffer();

            //CB796 - D365 SO to PE            
            salesLineOrig = SalesLine::findInventTransId(metSalesorderLineEntityStd.InventoryLotId, true).orig();

            if (this.OrderedSalesQuantity != salesLineOrig.SalesQty)
            {
                qtyFieldUpdated = true;
            }
        }
        if (this.METStatusCancelled)
        {
            metCancelSalesLine  = true;
        }

        boolean ret = next updateEntityDataSource(_entityCtx, _dataSourceCtx);


        if (_dataSourceCtx.name() == dataentitydatasourcestr(SalesOrderLineCDSV2Entity, SalesOrderLineEntity) &&
            _entityCtx.isDatabaseOperationUpdate())
        {
            SalesOrderLineV2Entity  metSalesorderLineEntityStd   = _dataSourceCtx.getBuffer();
            SalesLine               salesLine = SalesLine::findInventTransId(metSalesorderLineEntityStd.InventoryLotId, true);

            if (metCancelSalesLine)
            {
                salesLine.metCancelSalesOrderLine();
                this.metUpdateLineindicator(salesLine, true);
            }
            if (qtyFieldUpdated)
            {
                this.metUpdateLineindicator(salesLine, false);
            }
        } 

        return ret;
    }

    /// <summary>
    /// Update Line Indicator
    /// </summary>
    /// <param name = "_salesLine">SalesLine</param>
    /// <param name = "_doCancel">boolean</param>
    public void metUpdateLineindicator(SalesLine _salesLine, boolean _doCancel)
    {
        METSalesLine    metSalesLineUpdate;
        SalesLine       salesLineUpdate;

        try
        {
            ttsbegin;
            if(_doCancel)
            {
                while select forUpdate metSalesLineUpdate
                    exists join salesLineUpdate
                        where metSalesLineUpdate.SalesLine == salesLineUpdate.RecId
                        && salesLineUpdate.SalesStatus == SalesStatus::Canceled
                        && salesLineUpdate.RecId == _salesLine.RecId
                {
                    metSalesLineUpdate.LineIndicator = METLineIndicator::D;
                    metSalesLineUpdate.update();
                }
            }
            else
            {              
                while select forUpdate metSalesLineUpdate
                    exists join salesLineUpdate
                        where metSalesLineUpdate.SalesLine == salesLineUpdate.RecId
                        && salesLineUpdate.SalesId == _salesLine.SalesId
                        && salesLineUpdate.SalesStatus != SalesStatus::Canceled
                        && salesLineUpdate.RecId == _salesLine.RecId
                {
                    metSalesLineUpdate.LineIndicator = METLineIndicator::A;
                    metSalesLineUpdate.update();
                }

                metSalesLineUpdate.clear();
                salesLineUpdate.clear();

                while select forUpdate metSalesLineUpdate
                    exists join salesLineUpdate
                        where metSalesLineUpdate.SalesLine == salesLineUpdate.RecId
                        && salesLineUpdate.SalesId == _salesLine.SalesId
                        && metSalesLineUpdate.LineIndicator != METLineIndicator::A
                        && salesLineUpdate.SalesStatus != SalesStatus::Canceled
                        && salesLineUpdate.RecId != _salesLine.RecId
                {
                    metSalesLineUpdate.LineIndicator = METLineIndicator::U;
                    metSalesLineUpdate.update();
                }
            }
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch
        {
            throw error("@MET:UnhandledError");
        }
    }

    /// <summary>
    /// Add new datasources to the mapping
    /// </summary>
    /// <param name = "_mapping">EntityDataSourceToFieldMapping</param>
    /// <returns>The container of EntityDataSourceToFieldMapping</returns>
    public static container getEntityDataSourceToFieldMapping(container _mapping)
    {
        container mapping = next getEntityDataSourceToFieldMapping(_mapping);
        
        mapping += [[dataEntityDataSourceStr(SalesOrderLineCDSV2Entity, SalesOrderLineEntity), tablenum(METSalesLine), fieldstr(SalesOrderLineCDSV2Entity, METSalesLineRecId)]];

        return mapping;
    }
